p=argparse.ArgumentParser();p.add_argument('raw');p.add_argument('base');p.add_argument('output');p.add_argument('--frame',required=True);p.add_argument('--scale',type=float,required=True);p.add_argument('--tx',type=float,default=0);p.add_argument('--ty',type=float,required=True);args=p.parse_args();G=Path(__file__).resolve().parent;R=G.parent;O=Path(args.output)
